import { useState } from 'react';
import { Box, Stack, Tab, Tabs, Typography } from '@mui/material';
import type { BatchPreview as Preview } from '../../../types/cosmosColumns';

type PreviewTab = 'configRows' | 'alter' | 'etl';
const TABS: Array<[PreviewTab, string]> = [['configRows', 'Config rows'], ['alter', 'ALTER'], ['etl', 'What the ETL runs']];

/** What the batch will write and run, generated by the backend from the same rules Apply uses. */
/** `applied`: after an Apply empties the batch, what that batch did (until a new column is picked). */
const BatchPreview = ({ preview, count, tables, sources, applied }: {
  preview: Preview | null; count: number; tables: number; sources: number;
  applied?: { batchId: string; preview: Preview } | null;
}) => {
  const shown = count === 0 && applied ? applied.preview : preview;
  const [tab, setTab] = useState<PreviewTab>('configRows');
  return (
    <Stack spacing={1}>
      <Stack direction="row" justifyContent="space-between" alignItems="center">
        <Typography variant="overline" color="text.secondary">{count === 0 && applied ? `What batch ${applied.batchId} did` : 'What this batch will do'}</Typography>
        {count > 0 && (
          <Typography variant="caption" color="text.secondary">
            {count} config row{count === 1 ? '' : 's'} (one per column, covering the selected tables) · {tables} ALTER statement{tables === 1 ? '' : 's'} · {sources} ETL source quer{sources === 1 ? 'y' : 'ies'}
          </Typography>
        )}
      </Stack>
      <Tabs value={tab} onChange={(_, v: PreviewTab) => setTab(v)} sx={{ minHeight: 32 }}>
        {TABS.map(([v, label]) => <Tab key={v} value={v} label={label} sx={{ minHeight: 32, py: 0.5, fontSize: 13 }} />)}
      </Tabs>
      <Box component="pre" sx={{ m: 0, p: 1.5, bgcolor: 'action.hover', border: 1, borderColor: 'divider', borderRadius: 1, fontFamily: 'monospace', fontSize: 12, overflow: 'auto', maxHeight: 360 }}>
        {shown && (count > 0 || applied) ? shown[tab] : count === 0 ? '-- add columns to the batch to see the config rows, ALTERs and ETL lines for all of them together' : '-- loading…'}
      </Box>
    </Stack>
  );
};

export default BatchPreview;
